insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900400, 'de300000-0000-4000-a000-000000000001', 900200, 'Por fin la millepora está cogiendo color en las puntas 💜 Tres meses estable con KH en 8,2 y nada de picos. La paciencia en reef es literal. #reef #sps', array['/wiki-media/Acuarios/Acuario%20marino%20%E2%80%94%20arrecife%20de%20coral%20(reef)/Especies%20habituales/Corales/Acropora_millepora.webp']::text[], '2026-10-22T09:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900401, 'de300000-0000-4000-a000-000000000002', 900202, 'Poda de mantenimiento hecha. Dejo la hygrophila más baja para que entre luz al primer plano. ¿Qué os parece la nueva línea del musgo? #aquascaping #plantado', array['/wiki-media/Aquascaping/Principios/Principios.webp']::text[], '2026-10-21T08:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900402, 'de300000-0000-4000-a000-000000000003', 900204, 'Tres meses con mi primer acuario 🎉 Gracias a todos los que me ayudasteis con el ciclado. Lo siguiente: aprender a no comprar todos los peces que me gustan 😂 #principiantes', array['/wiki-media/Acuarios/Acuario%20dulce%20tropical%20de%20comunidad/Acuario_tropical_comunidad.webp']::text[], '2026-10-20T07:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900403, 'de300000-0000-4000-a000-000000000004', 900205, 'Cambio diario hecho. Agua a 29,5 °C, conductividad en 90 µS. Los discos ya comen de la mano. #discos', array['/wiki-media/Acuarios/Acuario%20de%20discus/Especies%20habituales/Peces/Symphysodon_discus.webp']::text[], '2026-10-22T06:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900404, 'de300000-0000-4000-a000-000000000005', 900206, 'Empieza a bajar la temperatura del estanque: 15 °C esta mañana. Toca reducir la comida y pasar al pienso de germen de trigo. #koi #estanques', array['/wiki-media/Acuarios/Estanques%20koi/Estanque_koi.webp']::text[], '2026-10-19T05:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900405, 'de300000-0000-4000-a000-000000000006', 900207, 'Recordatorio para quien empieza: un oranda adulto mide 25-30 cm. Nada de peceras redondas, por favor 🙏 #goldfish #aguafria', array['/wiki-media/Acuarios/Acuario%20de%20agua%20fr%C3%ADa%20%20goldfish/Especies%20habituales/Peces/Goldfish_oranda.webp']::text[], '2026-10-18T04:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900406, 'de300000-0000-4000-a000-000000000007', 900208, 'Mis corydoras pusieron huevos en el cristal 😍 ¿Los separo o los dejo a su suerte? #corydoras', array['/wiki-media/Acuarios/Acuario%20dulce%20tropical%20de%20comunidad/Especies%20habituales/Peces/Corydoras_aeneus.webp']::text[], '2026-10-21T03:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900407, 'de300000-0000-4000-a000-000000000008', 900209, 'Seis meses de nano reef. El secreto no es el equipo, es la constancia: cambio del 10 % todos los domingos, sin excusas. #nanoreef', array['/wiki-media/Acuarios/Nano%20acuario/Nano_acuario.webp']::text[], '2026-10-17T02:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900408, 'de300000-0000-4000-a000-000000000009', 900210, 'New frag rack in the sump is filling up fast. Anyone in Florida up for a frag swap this month? #reef #frags', array['/wiki-media/Biologia/Corales/Biologia_corales.webp']::text[], '2026-10-20T01:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900409, 'de300000-0000-4000-a000-000000000010', 900211, 'Der Glossostigma-Teppich schließt sich endlich. Woche 6, CO₂ und Licht gut abgestimmt. #iwagumi #aquascaping', array['/wiki-media/Aquascaping/Tecnicas/Tecnicas.webp']::text[], '2026-10-21T09:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900410, 'de300000-0000-4000-a000-000000000011', 900212, 'A cascata finalmente funciona sem respingar na parede 😅 Agora é esperar o musgo cobrir tudo. #paludario', array['/wiki-media/Acuarios/Paludario/Paludario.webp']::text[], '2026-10-16T08:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900411, 'de300000-0000-4000-a000-000000000012', 900213, 'Première portée de Crystal Red ! Une vingtaine de crevettes minuscules sur la mousse. #crevettes #caridina', array['/wiki-media/Acuarios/Acuario%20de%20gambas/Especies%20habituales/Invertebrados/Caridina_cantonensis_CRS.webp']::text[], '2026-10-22T07:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900412, 'de300000-0000-4000-a000-000000000013', 900214, 'Due discus hanno iniziato a pulire il vaso: forse una coppia in arrivo 🤞 #discus', array['/wiki-media/Acuarios/Acuario%20de%20discus/Especies%20habituales/Peces/Symphysodon_aequifasciatus.webp']::text[], '2026-10-19T06:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900413, 'de300000-0000-4000-a000-000000000014', 900215, 'Mijn eerste garnalen zijn binnen! Twaalf blauwe Neocaridina. Tips zijn welkom 💙 #garnalen', array['/wiki-media/Acuarios/Acuario%20de%20gambas/Especies%20habituales/Invertebrados/Neocaridina_davidi_Blue.webp']::text[], '2026-10-21T05:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900414, 'de300000-0000-4000-a000-000000000015', 900216, 'Nowe CBS w krewetkarium. Parametry stabilne od tygodnia, TDS 240. #krewetki', array['/wiki-media/Acuarios/Acuario%20de%20gambas/Especies%20habituales/Invertebrados/Caridina_cantonensis_CBS.webp']::text[], '2026-10-20T04:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900415, 'de300000-0000-4000-a000-000000000001', null, 'Consejo rápido: antes de culpar a la luz, mide fosfatos y nitratos. El 80 % de los problemas de color en SPS que veo son de nutrientes. @tomas_nano tú lo sabes bien 😉 #reef', array['/wiki-media/Equipamiento/Tests/Tests.webp']::text[], '2026-10-15T03:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900416, 'de300000-0000-4000-a000-000000000002', null, 'Taller gratuito de aquascaping este sábado en Madrid. Traed vuestras dudas sobre CO₂ y abonado. #quedada #aquascaping', array['/wiki-media/Equipamiento/CO2/CO2.webp']::text[], '2026-10-14T02:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900419, 'de300000-0000-4000-a000-000000000003', null, 'Pregunta tonta: ¿cada cuánto limpiáis el filtro? El mío tiene la esponja marrón y me da miedo tocarlo. #principiantes', '{}'::text[], '2026-10-17T08:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900420, 'de300000-0000-4000-a000-000000000007', null, 'Probando la calculadora de cambio de agua de Tankily: con un 30 % bajo los nitratos de 40 a 29. Muy útil 🙌 #nitratos', '{}'::text[], '2026-10-19T07:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900421, 'de300000-0000-4000-a000-000000000009', null, 'Quarantine every fish. Every single one. Learned it the hard way with marine ich. #reef #quarantine', array['/wiki-media/Enfermedades/Parasitarias/Oodinium.webp']::text[], '2026-10-13T06:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900422, 'de300000-0000-4000-a000-000000000006', null, 'Los goldfish de cuerpo alargado y los de velo NO deberían ir juntos: los rápidos les quitan la comida a los lentos. #goldfish', '{}'::text[], '2026-10-12T05:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900423, 'de300000-0000-4000-a000-000000000004', null, 'Osmosis + remineralizador: mis números para discos salvajes. GH 3, KH 2, 90 µS. ¿Cómo lo tenéis vosotros? #discos', array['/wiki-media/Equipamiento/Filtros/Filtros.webp']::text[], '2026-10-11T04:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900424, 'de300000-0000-4000-a000-000000000008', 900209, 'Los ocellaris ya duermen en la Stylophora. No es una anémona, pero a ellos les vale 😄 #nanoreef #payasos', array['/wiki-media/Acuarios/Acuario%20marino%20%E2%80%94%20arrecife%20de%20coral%20(reef)/Especies%20habituales/Peces/Amphiprion_ocellaris.webp']::text[], '2026-10-22T03:51:17.767Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, creado_en) overriding system value values (900425, 'de300000-0000-4000-a000-000000000010', null, 'Tipp: Licht nicht gleich auf 100 %. Zwei Wochen mit 60 % starten spart euch viel Algenärger. #aquascaping', array['/wiki-media/Equipamiento/Iluminacion/Iluminacion.webp']::text[], '2026-10-10T02:51:17.767Z');
