insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900600, 900400, 'de300000-0000-4000-a000-000000000008', '¡Qué color! ¿Qué espectro usas en la Radion?', '2026-10-22T12:15:17.767Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900601, 900400, 'de300000-0000-4000-a000-000000000001', '@tomas_nano el AB+ de Ecotech, con los azules al 90 %.', '2026-10-22T12:18:10.567Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900602, 900400, 'de300000-0000-4000-a000-000000000009', 'Beautiful colors on that millepora 🔥', '2026-10-22T12:21:03.367Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900603, 900401, 'de300000-0000-4000-a000-000000000010', 'Sehr schön! Die Moos-Linie gibt viel Tiefe.', '2026-10-21T12:23:56.167Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900604, 900401, 'de300000-0000-4000-a000-000000000003', 'Algún día tendré un acuario así 😍', '2026-10-21T12:26:48.967Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900605, 900401, 'de300000-0000-4000-a000-000000000002', '@marta_empieza ¡seguro que sí! Empieza con plantas fáciles y paciencia.', '2026-10-21T12:29:41.767Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900606, 900402, 'de300000-0000-4000-a000-000000000002', '¡Enhorabuena, Marta! Tres meses es cuando empieza lo bueno.', '2026-10-20T12:32:34.567Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900607, 900402, 'de300000-0000-4000-a000-000000000007', 'Felicidades 🎉 Ojo con el goldfish con los neones: necesitan temperaturas distintas.', '2026-10-20T12:35:27.367Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900608, 900402, 'de300000-0000-4000-a000-000000000006', 'Totalmente de acuerdo con Sofía: el oranda estaría mejor en agua fría.', '2026-10-20T12:38:20.167Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900609, 900402, 'de300000-0000-4000-a000-000000000003', 'Gracias! Lo vi en la compatibilidad del tanque, estoy buscándole un hogar mejor 🙈', '2026-10-20T12:41:12.967Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900610, 900403, 'de300000-0000-4000-a000-000000000013', 'Ottimi parametri! Anche io tengo i miei a 29-30 °C.', '2026-10-22T12:44:05.767Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900611, 900403, 'de300000-0000-4000-a000-000000000004', '@marco_discus ¡grazie! Los salvajes agradecen el agua muy blanda.', '2026-10-22T12:46:58.567Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900612, 900404, 'de300000-0000-4000-a000-000000000006', 'En Zaragoza ya estamos igual. ¿Dejas de alimentar por debajo de 10 °C?', '2026-10-19T12:49:51.367Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900613, 900404, 'de300000-0000-4000-a000-000000000005', 'Sí, por debajo de 8-10 °C nada de comida. Su digestión se para.', '2026-10-19T12:52:44.167Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900614, 900406, 'de300000-0000-4000-a000-000000000012', 'Si tu veux des alevins, sépare les œufs dans une petite boîte avec du bleu de méthylène.', '2026-10-21T12:55:36.967Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900615, 900406, 'de300000-0000-4000-a000-000000000003', 'Yo los dejaría, a ver si alguno sale adelante 🤞', '2026-10-21T12:58:29.767Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900616, 900406, 'de300000-0000-4000-a000-000000000007', 'Los dejé y hoy vi dos alevines escondidos en el musgo 😍', '2026-10-21T13:01:22.567Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900617, 900407, 'de300000-0000-4000-a000-000000000001', 'Gran verdad. La constancia gana a cualquier gadget.', '2026-10-17T13:04:15.367Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900618, 900408, 'de300000-0000-4000-a000-000000000001', 'If you ever come to Valencia, frag swap guaranteed 😄', '2026-10-20T13:07:08.167Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900619, 900409, 'de300000-0000-4000-a000-000000000002', 'Qué limpio queda ese iwagumi, Lukas.', '2026-10-21T13:10:00.967Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900620, 900411, 'de300000-0000-4000-a000-000000000015', 'Gratulacje! Pierwsze młode to najlepsze uczucie.', '2026-10-22T13:12:53.767Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900621, 900411, 'de300000-0000-4000-a000-000000000014', 'Zo mooi! Ik hoop dat mijn garnalen ook babies krijgen.', '2026-10-22T13:15:46.567Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900622, 900413, 'de300000-0000-4000-a000-000000000012', 'Bienvenue ! Garde l’eau stable et ne surnourris pas.', '2026-10-21T13:18:39.367Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900623, 900413, 'de300000-0000-4000-a000-000000000015', 'Stabilne parametry to podstawa. Powodzenia!', '2026-10-21T13:21:32.167Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900624, 900415, 'de300000-0000-4000-a000-000000000008', 'Culpable 🙋‍♂️ Medí fosfatos y estaban por las nubes.', '2026-10-15T13:24:24.967Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900625, 900416, 'de300000-0000-4000-a000-000000000003', '¡Me apunto! ¿Hay que llevar algo?', '2026-10-14T13:27:17.767Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900627, 900419, 'de300000-0000-4000-a000-000000000002', 'Nunca bajo el grifo: enjuágala en agua del propio acuario y solo cuando baje el caudal.', '2026-10-17T13:33:03.367Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900629, 900419, 'de300000-0000-4000-a000-000000000003', '¡Gracias! Pensé que estaba sucia de verdad 😅', '2026-10-17T13:38:48.967Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900630, 900421, 'de300000-0000-4000-a000-000000000001', 'Amén. Cuarentena siempre.', '2026-10-13T13:41:41.767Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900631, 900424, 'de300000-0000-4000-a000-000000000001', 'Si no tiene anémona, la Stylophora es la sustituta oficial 😂', '2026-10-22T13:44:34.567Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, creado_en) overriding system value values (900632, 900425, 'de300000-0000-4000-a000-000000000002', 'Muy importante. La mitad de mis algas del primer año fueron por eso.', '2026-10-10T13:47:27.367Z');
insert into public.foro_hilos (id, categoria, usuario_id, tanque_id, titulo, contenido, fijado, creado_en, ultima_actividad) overriding system value values (900700, 'principiantes', 'de300000-0000-4000-a000-000000000003', 900204, '¿Es normal que el agua se ponga blanca tras montar el acuario?', 'Monté el acuario hace cinco días y el agua se ha puesto lechosa. No tengo peces todavía. ¿Hago un cambio de agua?', false, '2026-08-04T09:51:17.767Z', '2026-08-04T09:51:17.767Z');
insert into public.foro_respuestas (id, hilo_id, usuario_id, contenido, creado_en) overriding system value values (903000, 900700, 'de300000-0000-4000-a000-000000000002', 'Es un pico bacteriano, normal en un acuario recién montado. No cambies agua: se aclara solo en unos días mientras se asienta el filtro.', '2026-08-04T17:03:17.767Z');
