insert into public.foro_hilos (id, categoria, usuario_id, tanque_id, titulo, contenido, fijado, creado_en, ultima_actividad) overriding system value values (900701, 'reef', 'de300000-0000-4000-a000-000000000008', 900209, 'Puntas blancas en la Stylophora: ¿luz o nutrientes?', 'Desde hace una semana veo las puntas de la Stylophora más claras. Nitratos en 2 y fosfatos en 0,01. Luz al 70 %.', false, '2026-09-23T09:51:17.767Z', '2026-09-23T09:51:17.767Z');
insert into public.foro_respuestas (id, hilo_id, usuario_id, contenido, creado_en) overriding system value values (903003, 900701, 'de300000-0000-4000-a000-000000000001', 'Con nitratos en 2 y fosfatos en 0,01 vas muy justo de nutrientes. Sube un poco la alimentación antes de tocar la luz.', '2026-09-23T17:03:17.767Z');
